'use strict';
const NOTES_KINDS={troubleshooting:['Troubleshooting','amber'],error:['Error','red'],solution:['Solution','green'],information:['Information','blue'],reminder:['Reminder','purple'],custom:['Sticky note','neutral']};
let notesTimer=null,notesRange=null,notesResize=null,notesSelectionRoot=null,notesDocumentRange=null;
const notesId=()=>('note-'+Date.now().toString(36)+Math.random().toString(36).slice(2,8));
function notesModel(){if(!state.notes||typeof state.notes!=='object'||!Array.isArray(state.notes.pages))state.notes={version:1,pages:[],selected:null};const n=state.notes;n.pages=n.pages.filter(p=>p&&typeof p==='object'&&typeof p.html==='string'&&typeof p.id==='string');for(const p of n.pages){if(!Array.isArray(p.stickies))p.stickies=[];p.stickies=p.stickies.filter(s=>s&&typeof s.id==='string'&&typeof s.html==='string');}if(!n.pages.length){const id=notesId();n.pages.push({id,name:'Untitled note',html:'<p></p>',stickies:[]});n.selected=id}if(!n.pages.some(p=>p.id===n.selected))n.selected=n.pages[0].id;return n}
function notesPage(){const n=notesModel();return n.pages.find(p=>p.id===n.selected)}
function notesCommit(){clearTimeout(notesTimer);const editor=$('notes-editor');if(!editor||active!=='notes'||editor.dataset.pageId!==notesPage()?.id)return;if(window.DevDenCollab?.isGroupActive?.()&&!window.DevDenCollab.notesEditable(notesPage().id))return;const page=notesPage();editor.querySelectorAll('.notes-task input[type=checkbox]').forEach(box=>{if(box.checked)box.setAttribute('checked','');else box.removeAttribute('checked')});const clean=editor.cloneNode(true);clean.querySelectorAll('#notes-drawing-tools,#notes-image-tools').forEach(el=>el.remove());clean.querySelectorAll('.notes-drawing-selected,.notes-figure-selected').forEach(el=>el.classList.remove('notes-drawing-selected','notes-figure-selected'));page.html=notesSanitize(clean.innerHTML);notesCaptureStickies(page);const name=$('notes-name');if(name)page.name=name.value.trim().slice(0,80)||'Untitled note';try{checkpoint();const key=toolkitStorageKey('devden-toolkit-v2');if(localStorage.getItem(key)!==JSON.stringify(state))throw Error('Browser storage is full');const status=$('notes-status');if(status)status.textContent='Saved locally';}catch{const status=$('notes-status');if(status)status.textContent='Storage full: export a project backup now';}}
function notesLeavePage(){const id=notesPage()?.id;notesCommit();window.dispatchEvent(new Event('devden-notes-blur'));if(id&&window.DevDenCollab?.isGroupActive?.())void window.DevDenCollab.finishEdit({kind:'notes',id});}
function notesRefreshPageList(){const select=$('notes-page-select');if(!select)return;const n=notesModel();const markup=n.pages.map((p,i)=>`<option value="${esc(p.id)}">${i+1}. ${esc(p.name)}</option>`).join('');if(select.dataset.options!==markup){select.innerHTML=markup;select.dataset.options=markup;}select.value=n.selected;}
function notesQueue(){const status=$('notes-status');if(status)status.textContent='Saving…';clearTimeout(notesTimer);notesTimer=setTimeout(notesCommit,450)}
function notesSanitize(html){const wrap=document.createElement('div');wrap.innerHTML=html;wrap.querySelectorAll('script,style,iframe,object,embed,form,link,meta,video,audio,svg').forEach(n=>n.remove());const walker=document.createTreeWalker(wrap,NodeFilter.SHOW_ELEMENT);let node;while(node=walker.nextNode()){for(const attr of [...node.attributes]){const key=attr.name.toLowerCase(),value=attr.value;if(key.startsWith('on')||key==='srcdoc'||key==='href'&&/^\s*(javascript|data):/i.test(value)||key==='src'&&!(/^data:image\/(png|jpeg|webp|gif);base64,/i.test(value))||key==='style'&&!['IMG','SPAN','P','DIV','TABLE','TD','TH','UL','OL','LI'].includes(node.tagName))node.removeAttribute(attr.name)}if(node.tagName==='IMG'&&!/^data:image\/(png|jpeg|webp|gif);base64,/i.test(node.getAttribute('src')||''))node.removeAttribute('src');}return wrap.innerHTML}
function notesSelection(){const sel=window.getSelection();if(!sel.rangeCount)return;const range=sel.getRangeAt(0),target=range.commonAncestorContainer;const editor=$('notes-editor');const sticky=target.nodeType===1?target:target.parentElement;const root=sticky?.closest?.('.notes-sticky-body,.notes-sticky-title')||editor;if(root?.contains(target)){notesRange=range.cloneRange();notesSelectionRoot=root;if(root===editor)notesDocumentRange=range.cloneRange()}}
function notesFocus(forceEditor=false){const editor=$('notes-editor');const root=!forceEditor&&notesSelectionRoot?.isConnected?notesSelectionRoot:editor;root.focus({preventScroll:true});const sel=window.getSelection();if(notesRange&&root.contains(notesRange.commonAncestorContainer)){sel.removeAllRanges();sel.addRange(notesRange)}else{const range=document.createRange();range.selectNodeContents(root);range.collapse(false);sel.removeAllRanges();sel.addRange(range)}}
function notesInsert(node){notesFocus();const sel=window.getSelection();const range=sel.getRangeAt(0);range.deleteContents();range.insertNode(node);range.setStartAfter(node);range.collapse(true);sel.removeAllRanges();sel.addRange(range);notesSelection();notesQueue()}
function notesExec(command,value=null){notesFocus();document.execCommand(command,false,value);notesSelection();notesQueue()}
function notesCaptureStickies(page){const panel=$('notes-stickies-list');if(!panel)return;const previous=new Map(page.stickies.map(s=>[s.id,s]));page.stickies=[...panel.querySelectorAll('.notes-side-sticky')].map(el=>{const saved=previous.get(el.dataset.id)||{};return {id:el.dataset.id,kind:el.dataset.kind||'custom',title:notesSanitize(el.querySelector('.notes-sticky-title')?.innerHTML||''),html:notesSanitize(el.querySelector('.notes-sticky-body')?.innerHTML||''),...{anchor:saved.anchor||el.dataset.anchor||''}}})}
function notesCreateAnchor(id,kind){const editor=$('notes-editor');const sel=window.getSelection();const range=notesDocumentRange&&editor.contains(notesDocumentRange.commonAncestorContainer)?notesDocumentRange.cloneRange():null;let marker=document.createElement('span');marker.className='notes-anchor';marker.dataset.anchor=id;marker.dataset.tone=NOTES_KINDS[kind][1];marker.setAttribute('title','Linked side note');marker.setAttribute('contenteditable','false');marker.textContent='';if(range){if(!range.collapsed){const span=document.createElement('span');span.className='notes-highlight';span.dataset.tone=NOTES_KINDS[kind][1];span.dataset.anchor=id;span.append(range.extractContents());range.insertNode(span);marker=span}else range.insertNode(marker)}else editor.append(marker);notesRange=null;notesDocumentRange=null;notesSelectionRoot=editor;notesQueue();return id}
function notesHighlight(kind){const editor=$('notes-editor');if(!NOTES_KINDS[kind])return;const range=notesDocumentRange&&editor.contains(notesDocumentRange.commonAncestorContainer)?notesDocumentRange.cloneRange():null;if(!range||range.collapsed){alert('Select text in the document to highlight it.');return}const span=document.createElement('span');span.className='notes-highlight';span.dataset.tone=NOTES_KINDS[kind][1];span.append(range.extractContents());range.insertNode(span);notesRange=null;notesDocumentRange=null;notesQueue()}
function notesSticky(kind){notesCommit();const page=notesPage(),id=notesId(),title=NOTES_KINDS[kind][0];notesCreateAnchor(id,kind);page.stickies.push({id,kind,title,html:'<p></p>',anchor:id});notesDrawStickies();notesQueue();const card=$('notes-stickies-list')?.querySelector(`[data-id="${id}"]`);card?.querySelector('.notes-sticky-body')?.focus({preventScroll:true})}
function notesDrawStickies(){const page=notesPage(),panel=$('notes-stickies-list');if(!panel)return;const editor=$('notes-editor');const anchors=[...editor.querySelectorAll('[data-anchor]')].map(e=>e.dataset.anchor);const ordered=[...page.stickies].sort((a,b)=>{const ai=anchors.indexOf(a.id),bi=anchors.indexOf(b.id);return (ai<0?99999:ai)-(bi<0?99999:bi)});const template=document.createElement('template');template.innerHTML=ordered.map(s=>{const kind=NOTES_KINDS[s.kind]?s.kind:'custom',tone=NOTES_KINDS[kind][1];return `<article class="notes-side-sticky" data-id="${esc(s.id)}" data-kind="${esc(kind)}" data-anchor="${esc(s.anchor||s.id)}" data-tone="${tone}"><div class="notes-sticky-head"><span class="notes-sticky-label">${esc(NOTES_KINDS[kind][0])}</span><button type="button" data-sticky-action="jump" title="Jump to linked text">↗</button><button type="button" data-sticky-action="reanchor" title="Link to selected text or cursor position">◎</button><button type="button" data-sticky-action="remove" title="Remove sticky note">×</button></div><div class="notes-sticky-title" contenteditable="true" data-placeholder="Title">${notesSanitize(s.title||esc(NOTES_KINDS[kind][0]))}</div><div class="notes-sticky-body" contenteditable="true" data-placeholder="Write here…">${notesSanitize(s.html)}</div></article>`}).join('');const existing=new Map([...panel.children].map(el=>[el.dataset.id,el]));let cursor=panel.firstElementChild;for(const fresh of [...template.content.children]){let card=existing.get(fresh.dataset.id);if(card){existing.delete(fresh.dataset.id);for(const selector of ['.notes-sticky-title','.notes-sticky-body']){const target=card.querySelector(selector),source=fresh.querySelector(selector);if(!target.contains(document.activeElement)&&target.innerHTML!==source.innerHTML)target.innerHTML=source.innerHTML}card.dataset.anchor=fresh.dataset.anchor;}else card=fresh;if(card!==cursor)panel.insertBefore(card,cursor);cursor=card.nextElementSibling;}for(const card of existing.values())card.remove();$('notes-sticky-empty').hidden=ordered.length>0}
function notesReanchor(id,kind){notesCommit();const editor=$('notes-editor'),range=notesDocumentRange;if(!range||!editor.contains(range.commonAncestorContainer)){alert('Select text or place the cursor in the document first, then click ◎.');return}const old=editor.querySelector(`[data-anchor="${id}"]`);if(old&&!confirm('Change this sticky note’s linked text? The existing link will be replaced.'))return;if(old){if(old.classList.contains('notes-highlight'))old.replaceWith(...old.childNodes);else old.remove()}notesCreateAnchor(id,kind);notesDrawStickies()}
function notesMigrateInline(page){const box=document.createElement('div');box.innerHTML=page.html;const legacy=[...box.querySelectorAll('.notes-sticky')];if(!legacy.length)return;for(const node of legacy){const id=node.dataset.sticky||notesId(),kind=Object.keys(NOTES_KINDS).find(k=>NOTES_KINDS[k][1]===node.dataset.tone)||'custom';page.stickies.push({id,kind,title:node.querySelector('.notes-sticky-title')?.innerHTML||esc(NOTES_KINDS[kind][0]),html:notesSanitize(node.querySelector('.notes-sticky-body')?.innerHTML||'<p></p>'),anchor:id});const marker=document.createElement('span');marker.dataset.anchor=id;marker.dataset.tone=NOTES_KINDS[kind][1];marker.className='notes-anchor';marker.contentEditable='false';node.replaceWith(marker)}page.html=box.innerHTML;checkpoint()}
function notesImageNode(src){const figure=document.createElement('figure');figure.className='notes-figure';figure.contentEditable='false';figure.tabIndex=0;const img=document.createElement('img');img.src=src;img.alt='Embedded screenshot';img.dataset.width='medium';img.draggable=false;const caption=document.createElement('figcaption');caption.contentEditable='true';caption.dataset.placeholder='Add a caption…';figure.append(img,caption);return figure}
async function notesEmbedImage(file){const target=$('notes-editor');if(!file||!file.type.startsWith('image/'))return;const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();let src=canvas.toDataURL('image/webp',.78);if(!src.startsWith('data:image/webp'))src=canvas.toDataURL('image/jpeg',.75);if(src.length>2200000)throw Error('Image too large after compression. Resize it before adding.');const existing=JSON.stringify(state).length;if(existing+src.length>4000000)throw Error('This project is approaching the browser storage limit. Export a backup or use smaller images.');if(!target?.isConnected||target!==$('notes-editor')||window.DevDenCollab?.isGroupActive?.()&&!window.DevDenCollab.notesEditable(target.dataset.pageId))throw Error('Note changed or is locked. Add the image again.');notesInsert(notesImageNode(src));}
function notesAddImage(file){notesEmbedImage(file).catch(e=>alert(e.message))}

function notesInstallInk(page){
 const overlay=$('notes-ink-overlay'),toggle=$('notes-ink-toggle'),clear=$('notes-ink-clear'),editor=$('notes-editor');
 if(!overlay||!toggle||!editor)return;
 const strokes=()=>Array.isArray(page.ink)?page.ink:[];
 const ns='http://www.w3.org/2000/svg';let drawing=null;
 function paint(){overlay.replaceChildren();for(const stroke of strokes()){const line=document.createElementNS(ns,'polyline');line.setAttribute('points',stroke.points||'');line.setAttribute('fill','none');line.setAttribute('stroke',stroke.color||'#ae78df');line.setAttribute('stroke-width','3.2');line.setAttribute('stroke-linecap','round');line.setAttribute('stroke-linejoin','round');overlay.append(line)}}
 function size(){const w=editor.offsetWidth,h=Math.max(editor.offsetHeight,editor.scrollHeight);overlay.style.width=w+'px';overlay.style.height=h+'px';overlay.setAttribute('viewBox','0 0 1000 1400')}
 function point(e){const r=overlay.getBoundingClientRect();return Math.max(0,Math.min(1000,Math.round((e.clientX-r.left)*1000/r.width)))+','+Math.max(0,Math.min(1400,Math.round((e.clientY-r.top)*1400/r.height)))}
 toggle.onclick=()=>{const enabled=!overlay.classList.contains('enabled');overlay.classList.toggle('enabled',enabled);toggle.setAttribute('aria-pressed',String(enabled));toggle.classList.toggle('selected',enabled);clear.hidden=!enabled;size()};
 clear.onclick=()=>{if(!strokes().length)return;if(!confirm('Clear all drawings on this page?'))return;page.ink=[];paint();notesQueue()};
 overlay.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();size();drawing={id:crypto.randomUUID(),points:point(e),color:'#ae78df'};(page.ink ||= []).push(drawing);overlay.classList.add('is-drawing');overlay.setPointerCapture(e.pointerId);paint()});
 overlay.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const next=point(e);if(drawing.points.endsWith(next))return;drawing.points+=' '+next;paint()});
 const finish=()=>{if(!drawing)return;drawing=null;overlay.classList.remove('is-drawing');notesQueue()};overlay.addEventListener('pointerup',finish);overlay.addEventListener('pointercancel',finish);
 if(typeof ResizeObserver!=='undefined')new ResizeObserver(size).observe(editor);size();paint();
}
function notesPrintSections(){const n=state.notes;const pagesList=Array.isArray(n?.pages)?n.pages:[];const pages=document.createElement('div');pages.id='notes-print-pages';for(const page of pagesList){const sheet=document.createElement('section');sheet.className='notes-print-page';const heading=document.createElement('h1');heading.textContent=page.name;const body=document.createElement('div');body.className='notes-print-body';body.innerHTML=notesSanitize(page.html);body.querySelectorAll('#notes-image-tools,#notes-drawing-tools').forEach(el=>el.remove());for(const sticky of page.stickies||[]){const kind=NOTES_KINDS[sticky.kind]?sticky.kind:'custom';const note=document.createElement('aside');note.className='notes-sticky notes-print-sticky';note.dataset.tone=NOTES_KINDS[kind][1];const title=document.createElement('strong');title.textContent=NOTES_KINDS[kind][0]+': '+(new DOMParser().parseFromString(sticky.title,'text/html').body.textContent||'');const details=document.createElement('div');details.innerHTML=notesSanitize(sticky.html);note.append(title,details);const mark=[...body.querySelectorAll('[data-anchor]')].find(el=>el.dataset.anchor===sticky.id);if(mark){const position=mark.closest('p,div,li,h1,h2,h3')||mark;position.after(note)}else body.append(note)}sheet.append(heading,body);if(page.ink?.length){const overlay=document.createElementNS('http://www.w3.org/2000/svg','svg');overlay.setAttribute('class','notes-print-ink');overlay.setAttribute('viewBox','0 0 1000 1400');overlay.setAttribute('preserveAspectRatio','none');for(const stroke of page.ink){const line=document.createElementNS('http://www.w3.org/2000/svg','polyline');line.setAttribute('points',stroke.points||'');line.setAttribute('fill','none');line.setAttribute('stroke',stroke.color||'#9a63c9');line.setAttribute('stroke-width','3');line.setAttribute('stroke-linecap','round');line.setAttribute('stroke-linejoin','round');overlay.append(line)}sheet.append(overlay)}pages.append(sheet)}return pages}
const NOTES_EXPORT_CSS=`@page{size:A4;margin:15mm}html{background:white;color:#202832}body{font:11pt/1.45 Arial,sans-serif;margin:0}section{position:relative}section+section{break-before:page}svg.export-topology{display:block;width:100%;height:auto;max-height:205mm} .export-topology-section table{font-size:9pt}h1,h2,h3{break-after:avoid;color:#243b52}section>h1{font-size:19pt;border-bottom:1px solid #c6d0da;padding-bottom:8px}p{margin:0 0 .4em;orphans:2;widows:2}img{max-width:100%;max-height:230mm;height:auto;object-fit:contain}figure{margin:8px 0;break-inside:avoid}figcaption{color:#465566}table{width:100%;border-collapse:collapse;overflow-wrap:anywhere}td,th{border:1px solid #adb5bd;padding:4px}tr{break-inside:avoid}thead{display:table-header-group}aside{border:1px solid #adb5bd;padding:9px;margin:10px 0;background:#f5f7fa;break-inside:auto}aside strong{display:block}.notes-anchor{display:none}.notes-highlight{background:#fff2b0}.notes-print-body{overflow-wrap:anywhere}.notes-print-ink{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.notes-drawing{position:relative;max-width:100%;break-inside:avoid}.notes-drawing-art{width:100%;height:100%;box-sizing:border-box}.notes-drawing-line .notes-drawing-art{border-top:2px solid #333}.notes-drawing-box .notes-drawing-art{border:2px solid #333}.notes-print-canvas img{display:block;width:100%;max-height:260mm}*{print-color-adjust:exact;-webkit-print-color-adjust:exact}`;
function notesExportMarkup(canvases=[],documentTitle='Network documentation',onlyCurrent=false){
 notesCommit();const pages=notesPrintSections();if(onlyCurrent){const idx=notesModel().pages.findIndex(p=>p.id===notesPage()?.id);[...pages.children].forEach((p,i)=>{if(i!==idx)p.remove()});}
 for(const canvas of [...canvases].reverse()){const sheet=document.createElement('section');sheet.className='notes-print-page notes-print-canvas';const img=document.createElement('img');img.src=canvas.toDataURL('image/png');img.alt=documentTitle;sheet.append(img);pages.prepend(sheet)}
 pages.querySelectorAll('[contenteditable],[tabindex],[role="button"]').forEach(el=>{el.removeAttribute('contenteditable');el.removeAttribute('tabindex');el.removeAttribute('role')});
 pages.querySelectorAll('input[type=checkbox]').forEach(el=>el.replaceWith(document.createTextNode(el.hasAttribute('checked')?'☑ ':'☐ ')));
 pages.querySelectorAll('.notes-highlight').forEach(el=>el.style.backgroundColor=({amber:'#fff2b0',red:'#ffdddd',green:'#d9f4df',blue:'#dcecff',purple:'#edddff'})[el.dataset.tone]||'#fff2b0');
 pages.querySelectorAll('.notes-figure img').forEach(img=>{img.style.maxWidth='100%';img.style.height='auto';const sizes={small:'35%',medium:'65%',large:'100%',full:'100%'};if(!img.style.width)img.style.width=sizes[img.dataset.width]||'100%';});
 pages.querySelectorAll('td,th').forEach(el=>{el.style.border='1px solid #adb5bd';el.style.padding='4px'});
 pages.querySelectorAll('aside').forEach(el=>{el.style.border='1px solid #adb5bd';el.style.padding='9px';el.style.backgroundColor='#f5f7fa'});
 return pages;
}
function notesExportHTML(pages,title){return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'+esc(title)+'</title><style>'+NOTES_EXPORT_CSS+'</style></head><body>'+pages.innerHTML+'</body></html>'}
function notesPrint(canvases=[],documentTitle='Network documentation'){return printEditablePages(notesExportMarkup(canvases,documentTitle),documentTitle)}
function printEditablePages(pages,documentTitle){if(!pages.children.length){alert('No notes to export.');return}
 // Print an isolated semantic HTML document, never a screenshot of the editor.
 const win=window.open('','_blank');if(!win){document.getElementById('notes-print-pages')?.remove();document.body.append(pages);document.body.classList.add('notes-print');window.addEventListener('afterprint',()=>{document.body.classList.remove('notes-print');pages.remove()},{once:true});Promise.all([...pages.querySelectorAll('img')].map(img=>img.decode?.().catch(()=>{})||Promise.resolve())).then(()=>window.print());return}
 win.document.open();win.document.write(notesExportHTML(pages,documentTitle));win.document.close();
 Promise.all([...win.document.images].map(img=>img.decode?.().catch(()=>{})||Promise.resolve())).then(()=>{win.focus();win.print()});
}
async function notesCopyOneNote(){return copyEditableOneNote(notesExportMarkup([], 'Notes',true),'Notes')}
async function copyEditableOneNote(pages,title){const clipboard=pages.cloneNode(true);clipboard.querySelectorAll('.notes-anchor,svg').forEach(el=>el.remove());clipboard.querySelectorAll('aside').forEach(el=>{const div=document.createElement('div');div.style.cssText=el.style.cssText;div.append(...el.childNodes);el.replaceWith(div)});const html=notesExportHTML(clipboard,title);const status=$('notes-status');try{if(!navigator.clipboard?.write||typeof ClipboardItem==='undefined')throw Error('Clipboard unavailable');await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([html],{type:'text/html'}),'text/plain':new Blob([pages.innerText||pages.textContent],{type:'text/plain'})})]);if(status)status.textContent='Copied · paste into OneNote';else alert('Copied. Paste into OneNote using Ctrl+V.');}catch{const win=window.open('','_blank');if(!win){download('DevDen-documentation.html',html,'text/html;charset=utf-8');return}win.document.write(html);win.document.close();const range=win.document.createRange();range.selectNodeContents(win.document.body);win.getSelection().removeAllRanges();win.getSelection().addRange(range);win.focus();alert('Copy the selected document (Ctrl+C), then paste into OneNote.');}}
