function notesShowImageTools(img){let tray=$('notes-image-tools');tray?.remove();tray=document.createElement('div');tray.id='notes-image-tools';tray.className='notes-image-tools';tray.contentEditable='false';tray.innerHTML='<span>Image size</span><button data-size="small">Small</button><button data-size="medium">Medium</button><button data-size="large">Large</button><button data-size="full">Full</button><button id="notes-image-view">Enlarge</button><button id="notes-image-remove">Remove</button><span class="notes-image-hint">Drag bottom-right corner to resize</span>';img.closest('figure').append(tray);tray.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{img.dataset.width=b.dataset.size;img.style.width='';notesQueue()});tray.querySelector('#notes-image-view').onclick=()=>{$('notes-image-preview').src=img.src;$('notes-image-dialog').showModal()};tray.querySelector('#notes-image-remove').onclick=()=>{if(confirm('Remove image?')){img.closest('figure').remove();notesQueue()}};const onpointer=e=>{if(e.target!==img)return;const bounds=img.getBoundingClientRect();if(e.clientX<bounds.right-25||e.clientY<bounds.bottom-25)return;e.preventDefault();const initial=bounds.width,startX=e.clientX;img.setPointerCapture(e.pointerId);const move=m=>{img.style.width=Math.max(100,Math.min(900,initial+m.clientX-startX))+'px';img.dataset.width='custom'};const finish=()=>{img.removeEventListener('pointermove',move);img.removeEventListener('pointerup',finish);img.removeEventListener('pointercancel',finish);notesQueue()};img.addEventListener('pointermove',move);img.addEventListener('pointerup',finish);img.addEventListener('pointercancel',finish)};img.onpointerdown=onpointer}
