// Semantic project exports: diagrams are SVG for print, with native tables for editing.
function exportFilename(title){return title.replace(/[^a-z0-9_-]+/gi,'-')||'Network-documentation'}
function exportTable(headers,rows){const table=document.createElement('table');table.style.cssText='border-collapse:collapse;width:100%';const head=table.createTHead().insertRow();for(const name of headers){const cell=document.createElement('th');cell.textContent=name;head.append(cell)}const body=table.createTBody();for(const row of rows){const tr=body.insertRow();for(const value of row)tr.insertCell().textContent=String(value??'')}for(const cell of table.querySelectorAll('td,th'))cell.style.cssText='border:1px solid #9ca8b3;padding:4px';return table}
function exportSection(name){const section=document.createElement('section'),h=document.createElement('h1');h.textContent=name;section.append(h);return section}
function exportSubheading(section,name){const h=document.createElement('h2');h.textContent=name;section.append(h)}
function exportTopologySVG(view){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('export-topology');const items=[...topo.devices.map(d=>({x:d.x-100,y:d.y-65,w:200,h:130})),...topo.zones,...topo.notes.filter(n=>n.scope==='both'||n.scope===view).map(n=>({...n,w:n.w||270,h:n.h||120}))];const left=Math.min(...items.map(i=>i.x),0)-20,top=Math.min(...items.map(i=>i.y),0)-20,right=Math.max(...items.map(i=>i.x+i.w),200)+20,bottom=Math.max(...items.map(i=>i.y+i.h),100)+20;svg.setAttribute('viewBox',[left,top,right-left,bottom-top].join(' '));svg.setAttribute('width',right-left);svg.setAttribute('height',bottom-top);const add=(tag,attrs,txt)=>{const e=document.createElementNS(svg.namespaceURI,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);if(txt!==undefined)e.textContent=txt;svg.append(e);return e};const text=(x,y,t,extra={})=>add('text',{x,y,fill:'#172638','font-size':13,'font-family':'Arial, sans-serif',...extra},t);for(const z of topo.zones){const label=topoZoneText(z);add('rect',{x:z.x,y:z.y,width:z.w,height:z.h,fill:'#f1f5f9',stroke:z.color||'#667788','stroke-dasharray':'6 4'});text(z.x+8,z.y+18,label.name);text(z.x+8,z.y+z.h-8,label.network)}for(const l of topo.links){const a=topo.devices.find(d=>d.id===l.a),b=topo.devices.find(d=>d.id===l.b);if(!a||!b)continue;add('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:l.type==='crossover'?'#ad6231':'#62748a','stroke-width':2,'stroke-dasharray':l.type==='wireless'?'7 5':'none'});const spots=topoWireLabelPositions(a.x,a.y,b.x,b.y,a.type==='Node'?{w:0,h:0}:{w:120,h:84},b.type==='Node'?{w:0,h:0}:{w:120,h:84});for(const slot of ['a','middle','b'])if(l[view]?.[slot])text(spots[slot].x,spots[slot].y,l[view][slot],{'text-anchor':'middle',stroke:'white','stroke-width':3,'paint-order':'stroke'})}for(const d of topo.devices){if(d.type==='Node'){add('circle',{cx:d.x,cy:d.y,r:4,fill:'#334155'});continue}add('rect',{x:d.x-60,y:d.y-42,width:120,height:84,rx:8,fill:'#e7eef6',stroke:'#64748b'});for(const [i,value] of [d.type,d.name,view==='physical'?d.ports:d.ip].entries())text(d.x,d.y-16+i*22,value||'',{'text-anchor':'middle','font-size':i===2?11:13})}for(const n of topo.notes.filter(n=>n.scope==='both'||n.scope===view)){if(n.type==='chartMirror')continue;if(n.type==='sticky')add('rect',{x:n.x,y:n.y,width:n.w||155,height:n.h||92,fill:'#fff3cd',stroke:'#c8a95b'});for(const [i,line] of String(n.type==='sticky'?n.text:n[view]||'').split('\n').entries())text(n.x+5,n.y+16+i*16,line)}return svg}
function exportTopologySection(view,format){const section=exportSection(view==='physical'?'Physical topology':'Logical topology');section.classList.add('export-topology-section');if(format==='pdf'||format==='html')section.append(exportTopologySVG(view));exportSubheading(section,'Devices');section.append(exportTable(['Device','Type','Ports','IP address'],topo.devices.filter(d=>d.type!=='Node').map(d=>[d.name,d.type,d.ports,d.ip])));if(topo.zones.length){exportSubheading(section,'LAN / subnets');section.append(exportTable(['LAN','Subnet'],topo.zones.map(z=>{const t=topoZoneText(z);return[t.name,t.network]})))}if(topo.links.length){exportSubheading(section,'Connections');section.append(exportTable(['From','To','Cable','From label','Link label','To label'],topo.links.map(l=>[topo.devices.find(d=>d.id===l.a)?.name||l.a,topo.devices.find(d=>d.id===l.b)?.name||l.b,l.type,l[view]?.a,l[view]?.middle,l[view]?.b])))}for(const n of topo.notes.filter(n=>n.scope==='both'||n.scope===view)){if(n.type==='chartMirror'){exportSubheading(section,'Linked chart');for(const col of topoMirrorColumns(n))appendExportColumn(section,col);continue}const p=document.createElement('p');p.textContent=n.type==='sticky'?`${TOPO_STICKY_TYPES[topoStickyKind(n.stickyType)][0]}: ${n.text||''}`:n[view]||'';section.append(p)}return section}
function appendExportColumn(section,col){exportSubheading(section,col.name);const p=document.createElement('p');p.textContent=`Subnet: ${col.cidr||'—'} | Gateway: ${col.gateway||'—'}`;section.append(p,exportTable(['Device','Type','IP','Port','Connected via'],col.rows.map(r=>[r.name,r.type,r.ip,r.port,r.peer])))}
function exportChartSection(){const section=exportSection('Network Chart');for(const col of topoMirrorColumns({sourceIds:chartData().subnets.map(s=>s.id)}))appendExportColumn(section,col);return section}
// Minimal Office Open XML writer (uncompressed ZIP, no external libraries).
function exportZip(files){const encoder=new TextEncoder(),chunks=[],directory=[];let offset=0,size=0;const crc=bytes=>{let c=0xffffffff;for(const b of bytes){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0)}return(c^0xffffffff)>>>0};const header=(n,fields)=>{const a=new Uint8Array(n),v=new DataView(a.buffer);for(const [at,value,width] of fields)width===2?v.setUint16(at,value,true):v.setUint32(at,value,true);return a};for(const [name,value] of Object.entries(files)){const key=encoder.encode(name),data=typeof value==='string'?encoder.encode(value):value,c=crc(data),local=header(30,[[0,0x04034b50,4],[4,20,2],[14,c,4],[18,data.length,4],[22,data.length,4],[26,key.length,2]]),central=header(46,[[0,0x02014b50,4],[4,20,2],[6,20,2],[16,c,4],[20,data.length,4],[24,data.length,4],[28,key.length,2],[42,offset,4]]);chunks.push(local,key,data);directory.push(central,key);offset+=local.length+key.length+data.length;size+=central.length+key.length}const count=Object.keys(files).length;return new Blob([...chunks,...directory,header(22,[[0,0x06054b50,4],[8,count,2],[10,count,2],[12,size,4],[16,offset,4]])],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})}
async function exportWord(pages,title){const xml=s=>String(s??'').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');const files={},rels=[];let count=0;const ns='http://schemas.openxmlformats.org/wordprocessingml/2006/main',rel='http://schemas.openxmlformats.org/officeDocument/2006/relationships';const run=(value,props='')=>`<w:r>${props?`<w:rPr>${props}</w:rPr>`:''}${String(value).split('\n').map((t,i)=>(i?'<w:br/>':'')+`<w:t xml:space="preserve">${xml(t)}</w:t>`).join('')}</w:r>`;const para=(runs,props='')=>`<w:p>${props?`<w:pPr>${props}</w:pPr>`:''}${runs}</w:p>`;const image=async el=>{try{const img=new Image();img.src=el.src;await img.decode();const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;c.getContext('2d').drawImage(img,0,0);const data=c.toDataURL('image/png').split(',')[1],id=++count;files[`word/media/image${id}.png`]=Uint8Array.from(atob(data),x=>x.charCodeAt(0));rels.push(`<Relationship Id="rId${id}" Type="${rel}/image" Target="media/image${id}.png"/>`);const width=Math.min(580,Math.max(1,img.naturalWidth)),height=width*img.naturalHeight/img.naturalWidth,scale=Math.min(1,850/height),cx=Math.round(width*scale*9525),cy=Math.round(height*scale*9525);return `<w:r><w:drawing><wp:inline><wp:extent cx="${cx}" cy="${cy}"/><wp:docPr id="${id}" name="Image ${id}"/><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="${id}" name="Image ${id}"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rId${id}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${cx}" cy="${cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r>`}catch{return run('[Image could not be embedded]')}};const inline=async(node,props='')=>{if(node.nodeType===3)return run(node.nodeValue,props);if(node.nodeType!==1)return '';const tag=node.tagName.toLowerCase();if(tag==='br')return '<w:r><w:br/></w:r>';if(tag==='img')return image(node);if(tag==='svg'||node.classList.contains('notes-anchor'))return '';if(['b','strong'].includes(tag)||node.style.fontWeight==='bold')props+='<w:b/>';if(['i','em'].includes(tag)||node.style.fontStyle==='italic')props+='<w:i/>';if(tag==='u'||node.style.textDecoration.includes('underline'))props+='<w:u w:val="single"/>';return(await Promise.all([...node.childNodes].map(n=>inline(n,props)))).join('')};const blocks=async root=>{let out='',pending='';const flush=()=>{if(pending){out+=para(pending);pending=''}};for(const node of root.childNodes){if(node.nodeType===3){if(node.nodeValue.trim())pending+=run(node.nodeValue);continue}if(node.nodeType!==1)continue;const tag=node.tagName.toLowerCase();if(tag==='table'){flush();const rows=[];for(const tr of node.rows){const cells=[];for(const td of tr.cells){const body=await blocks(td);cells.push(`<w:tc><w:tcPr><w:tcW w:w="0" w:type="auto"/>${td.colSpan>1?`<w:gridSpan w:val="${td.colSpan}"/>`:''}</w:tcPr>${body||para('')}</w:tc>`)}rows.push(`<w:tr>${cells.join('')}</w:tr>`)}out+=`<w:tbl><w:tblPr><w:tblW w:w="5000" w:type="pct"/><w:tblBorders>${['top','left','bottom','right','insideH','insideV'].map(x=>`<w:${x} w:val="single" w:sz="4" w:color="A0AAB5"/>`).join('')}</w:tblBorders></w:tblPr><w:tblGrid>${Array.from({length:Math.max(1,...[...node.rows].map(r=>[...r.cells].reduce((a,c)=>a+c.colSpan,0)))},()=>'<w:gridCol/>').join('')}</w:tblGrid>${rows.join('')}</w:tbl>`;continue}if(/^h[1-6]$/.test(tag)){flush();out+=para(await inline(node,`<w:b/><w:sz w:val="${tag==='h1'?36:28}"/>`),'<w:keepNext/>');continue}if(['section','div','aside','figure','ul','ol'].includes(tag)){flush();if(tag==='ul'||tag==='ol'){let i=0;for(const li of node.children)out+=para(run(tag==='ul'?'• ':`${++i}. `)+await inline(li));}else out+=await blocks(node);continue}if(['p','li','figcaption'].includes(tag)){flush();out+=para(await inline(node));continue}if(tag==='svg'){flush();continue}if(tag==='hr'){flush();out+=para(run('────────────────'));continue}pending+=await inline(node)}flush();return out};let body=para(run(title,'<w:b/><w:sz w:val="40"/>'));for(const section of pages.children)body+=await blocks(section);const decl='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';files['word/document.xml']=decl+`<w:document xmlns:w="${ns}" xmlns:r="${rel}" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:body>${body}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="850" w:bottom="850" w:left="850" w:right="850"/></w:sectPr></w:body></w:document>`;files['[Content_Types].xml']=decl+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>';files['_rels/.rels']=decl+`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="${rel}/officeDocument" Target="word/document.xml"/></Relationships>`;files['word/_rels/document.xml.rels']=decl+`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${rels.join('')}</Relationships>`;download(exportFilename(title)+'.docx',exportZip(files),'application/vnd.openxmlformats-officedocument.wordprocessingml.document')}
